import{z as A,x as B,o as e,c as i,q as t,j as o,D as E,d as r,s as l,S as s}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"马尔萨斯到现代增长","description":"","frontmatter":{"title":"马尔萨斯到现代增长","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/malthus-to-modern.md","filePath":"econ/malthus-to-modern.md","lastUpdated":1791063341000}'),p={name:"econ/malthus-to-modern.md"};function d(h,a,m,_,c,u){const n=B("Mermaid");return e(),i("div",null,[a[2]||(a[2]=t('<h1 id="马尔萨斯到现代增长" tabindex="-1">马尔萨斯到现代增长 <a class="header-anchor" href="#马尔萨斯到现代增长" aria-label="Permalink to &quot;马尔萨斯到现代增长&quot;">​</a></h1><div class="epigraph"><p>土地固定时，技术改善先变成人口，而不是人均收入；现代增长从这条人口反馈断开的那一刻才开始。</p><footer>—— 据 Malthus《人口原理》的土地约束；对照 Galor 统一增长理论</footer></div><p><a href="/econ/institutions-acemoglu">上一课</a>把制度写成比较发展的根本原因：产权与约束进入投资激励。制度解释<strong>谁</strong>能占有剩余，还不解释<strong>何时</strong>人均收入脱离生存水平。本课的缺口是对照两套动态：马尔萨斯——技术或制度改善被人口吃掉；现代增长——人力资本与人口转变让 \\(g\\) 留在人均上。错配与发展核算下一课才回到截面 \\(A\\)；本课先把时间上的阶段钉住。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>索洛与内生增长都在现代增长已经发生的世界上写 \\(n\\) 与 \\(g\\)。工业革命前的数百年，技术并非完全停滞，人均收入却几乎不动——改善表现为更多人，而不是更高的 \\(y\\)。Malthus 的缺口是土地（或固定资源）使人均产出对人口递减。统一增长（Galor 与 Weil 一类）要回答的是：同一套模型如何先复制马尔萨斯稳态，再内生地进入人口转变与持续 \\(g\\)。本课不是人口史综述，只关闭「制度一好，人均立刻永久上升」这句跳跃。</p><p><span class="marginnote">马尔萨斯稳态不是「没有技术」，而是技术的水平效应被 \\(n\\) 吃掉。这与索洛里 \\(s\\) 只有水平效应、增长靠 \\(g\\) 的分工同构，对象换成人口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>马尔萨斯块：生产含固定土地，\\(y\\) 随人口上升而下降；收入高于生存则生育或存活上升，\\(n\\) 内生，把 \\(y\\) 拉回生存。制度改善或一次性技术跳升，短期 \\(y\\) 升，长期人口更多、\\(y\\) 回来。现代块：人力资本回报上升 → 生育率下降、对每个孩子的教育上升 → 劳动力质量进入内生 \\(g\\)，人口不再吃掉人均。两块之间的触发可以是技术跨过阈值、或技能偏向使教育变得值得。</p>',8)),(e(),o(s,null,{default:E(()=>[l(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TECH%5B%22%E6%8A%80%E6%9C%AF%E6%88%96%E5%88%B6%E5%BA%A6%E6%94%B9%E5%96%84%22%5D%20--%3E%20MALT%5B%22%E9%A9%AC%E5%B0%94%E8%90%A8%E6%96%AF%EF%BC%9A%E4%BA%BA%E5%8F%A3%E2%86%91%EF%BC%8C%E4%BA%BA%E5%9D%87%E5%9B%9E%E6%9D%A5%22%5D%0A%20%20TECH%20--%3E%20MOD%5B%22%E7%8E%B0%E4%BB%A3%EF%BC%9A%E6%95%99%E8%82%B2%E2%86%91%EF%BC%8C%E7%94%9F%E8%82%B2%E2%86%93%22%5D%0A%20%20MOD%20--%3E%20G%5B%22%E4%BA%BA%E5%9D%87%20g%20%E6%8C%81%E7%BB%AD%22%5D%0A%20%20MALT%20--%3E%20WAIT%5B%22%E4%BB%8D%E5%9C%A8%E7%94%9F%E5%AD%98%E9%99%84%E8%BF%91%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>上一课的包容制度，在马尔萨斯块里主要改变人口规模与城市化，不一定改变长期人均。这不是否定 AJR，而是限制它适用的阶段：殖民起源样本已经是现代增长世界里的截面。</p><p><span class="marginnote">数字实例：从公元元年到 1800 年前后，世界人口大约从两三亿涨到十亿量级，而多数估计里人均收入几乎原地不动——上千年的技术进步果实几乎全部变现为「更多人」，而不是「每人更多」。这正是「水平效应被 \\(n\\) 吃掉」在数据上的样子。</span></p><h3 id="不要把-当索洛参数抄过来" tabindex="-1">不要把 \\(n\\) 当索洛参数抄过来 <a class="header-anchor" href="#不要把-当索洛参数抄过来" aria-label="Permalink to &quot;不要把 $n$ 当索洛参数抄过来&quot;">​</a></h3><p>索洛的 \\(n\\) 是摊薄资本的外生率。本课的 \\(n\\) 对人均收入有反馈。黄金律、Ramsey 都默认已经离开生存约束。把工业革命前的停滞读成「储蓄率太低」，是用错了阶段。</p><h3 id="生存约束与-不是同一个对象" tabindex="-1">生存约束与 \\(y^*\\) 不是同一个对象 <a class="header-anchor" href="#生存约束与-不是同一个对象" aria-label="Permalink to &quot;生存约束与 $y^*$ 不是同一个对象&quot;">​</a></h3><p>自然率课的 \\(y^*\\) 是充分就业潜在产出，已经在现代增长世界里。马尔萨斯的生存水平是人口反馈钉住的人均，对象是长期发展，不是周期缺口。</p><p>把当代衰退中的低收入写成「回到马尔萨斯」，会取消 Okun 与参与课已经钉住的松弛账户。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>土地递减使边际人口的产出落到生存线附近，技术的租被新人口分掉。一旦人力资本在生产中变得足够重要，父母用「少生优育」替代数量，劳动力质量与研发互补——接到内生增长与有偏技术：技能偏向可以正是人口转变的推手。脱离之后，制度才主要表现为截面 \\(A\\) 与 \\(K\\)，而不是再被人口完全吸收。</p>',9)),(e(),o(s,null,{default:E(()=>[l(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E4%BA%BA%E5%9D%87%E6%94%B6%E5%85%A5%E9%AB%98%E4%BA%8E%E7%94%9F%E5%AD%98%E7%BA%BF%22%5D%20--%3E%20F%5B%22%E7%94%9F%E8%82%B2%E7%8E%87%20n%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20F%20--%3E%20P%5B%22%E4%BA%BA%E5%8F%A3%E5%A2%9E%E5%8A%A0%22%5D%0A%20%20P%20--%3E%20L%5B%22%E4%BA%BA%E5%9D%87%E5%9C%9F%E5%9C%B0%E4%B8%8B%E9%99%8D%22%5D%0A%20%20L%20--%3E%20D%5B%22%E5%8A%B3%E5%8A%A8%E8%BE%B9%E9%99%85%E4%BA%A7%E5%87%BA%E9%80%92%E5%87%8F%22%5D%0A%20%20D%20--%3E%20YB%5B%22y%20%E8%A2%AB%E6%8B%89%E5%9B%9E%E7%94%9F%E5%AD%98%E7%BA%BF%22%5D%0A%20%20YB%20--%3E%20STOP%5B%22%E7%94%9F%E8%82%B2%E5%9B%9E%E5%88%B0%E6%9B%BF%E6%8D%A2%E6%B0%B4%E5%B9%B3%EF%BC%8C%E4%BA%BA%E5%8F%A3%E6%9A%82%E5%81%9C%E5%A2%9E%E9%95%BF%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>经验对照只点一句：人口转变与持续人均增长大致同期，先后在各国不同。本课不编年份因果。统一增长是对照装置，不是已经识别了每一个触发。</p><p><span class="marginnote">直觉类比：数量-质量替代像家里预算既定时「多生几个」与「供一个上大学」之间的选择。工资结构一旦开始重奖技能，把同样的育儿资源押在一个孩子的教育上就更划算；这个选择成为普遍行为后，人口数量就不再自动吞掉技术进步的果实。</span></p><p>土地约束松开之后，索洛的 \\(n\\) 才重新像参数：摊薄资本，而不是吃掉全部剩余。内生增长的研发部门也才站得住——马尔萨斯块里，研发的租同样会被新人口摊薄。AJR 的殖民截面已经位于现代块：人均收入差可以持久，正是因为人口反馈不再把 \\(y\\) 钉回生存。把工业革命前的停滞与当代穷国的低 \\(A\\) 写成同一句马尔萨斯，会取消发展核算。</p><p><span class="marginnote">疾病、战争可以暂时抬高人均（人口下降），仍是马尔萨斯机制，不是现代增长。看 \\(y\\) 的水平是否能在人口恢复后保住。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计生育方程，不把马尔萨斯写成当代贫困的唯一理论——当代穷国已部分进入现代增长，发展核算更贴。也不把 CIP 或资本流动当人口转变的原因。量化栏没有这条长期人口动态。</p><p><span class="marginnote">常见误区：初学者容易以为「马尔萨斯早被证伪了」。他错的是预测窗口，不是机制本身：只要固定资源还约束生产，人口反馈确实会把人均钉回生存线——这在工业革命前成立。他没料到的是人力资本回报上升触发少生优育，把这条反馈回路剪断了。</span></p><p>统一增长有多套触发（人力资本阈值、性别工资、结构转型），本课不选唯一。要禁止的只是：用现代索洛比较静态去读生存约束还在的经济。黄金律在马尔萨斯块里会被人口吃掉，计划者问题必须重写生育，不能把 \\(s\\) 当唯一按钮。</p><p>后课默认：增长主干里的 \\(n\\)、\\(g\\) 默认现代阶段；谈到工业革命前或极低收入，先问人口反馈是否还在。下一课回到截面：错配如何表现为同一个残差 \\(A\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>制度课解释激励；本课解释人均为何长期钉在生存线。</li><li>马尔萨斯：技术与制度的改善被人口吸收。</li><li>现代增长：人力资本与生育转变让 \\(g\\) 留在人均上。</li><li>索洛的外生 \\(n\\) 不适用于生存约束还在的阶段。</li><li>出处：Malthus《人口原理》；Galor 统一增长（与 Weil 等）的阶段对照。</li></ul>',11))])}const C=A(p,[["render",d]]);export{T as __pageData,C as default};
